{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "ExtractionOutput",
  "description": "Structured fields extracted from a raw support ticket. Output of the extraction LLM, input to the scoring LLM.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "ticket_id",
    "language",
    "intent",
    "product_area",
    "sentiment",
    "entities",
    "summary_de",
    "summary_en"
  ],
  "properties": {
    "ticket_id": {
      "type": "string",
      "description": "Pass-through identifier from the webhook payload. Not generated by the LLM."
    },
    "language": {
      "type": "string",
      "enum": ["de", "en", "other"],
      "description": "Dominant language of the ticket body."
    },
    "intent": {
      "type": "string",
      "enum": [
        "breakdown_emergency",
        "repair_request",
        "appointment_scheduling",
        "appointment_confirmation",
        "billing_question",
        "warranty_claim",
        "quote_request",
        "complaint",
        "other"
      ],
      "description": "Primary intent. If multiple, pick highest-stakes."
    },
    "product_area": {
      "type": "string",
      "enum": ["heating_system", "heat_pump", "service_contract", "billing", "unknown"],
      "description": "Which product or service area the ticket concerns."
    },
    "sentiment": {
      "type": "string",
      "enum": ["negative", "neutral", "positive"],
      "description": "Overall emotional tone of the ticket sender."
    },
    "entities": {
      "type": "object",
      "additionalProperties": false,
      "required": ["addresses", "phone_numbers", "order_ids", "error_codes"],
      "properties": {
        "addresses": {"type": "array", "items": {"type": "string"}},
        "phone_numbers": {"type": "array", "items": {"type": "string"}},
        "order_ids": {"type": "array", "items": {"type": "string"}},
        "error_codes": {"type": "array", "items": {"type": "string"}}
      }
    },
    "summary_de": {
      "type": "string",
      "maxLength": 200,
      "description": "Two-sentence summary in German."
    },
    "summary_en": {
      "type": "string",
      "maxLength": 200,
      "description": "Two-sentence summary in English."
    }
  }
}

parameters.jsCode:
// Tier multiplier: deterministic priority calculation
// Inputs: scoring output (current node input) + original webhook payload
// Output: combined record ready for storage

const severityScale = {
  low: 1,
  medium: 2,
  high: 4,
  critical: 8
};

const tierWeights = {
  A: 1.5,
  B: 1.0,
  C: 0.7
};

// Heating-season window per German tenancy case law: Oct 1 – Apr 30
function isHeatingSeason(isoDate) {
  const md = isoDate.slice(5, 10); // "MM-DD"
  return md >= "10-01" || md <= "04-30";
}

// Pull scoring output — dig through the Responses API wrapper
const raw = $input.item.json;
const scoring = raw.output[0].content[0].text;

// Pull original webhook payload
const webhook = $('Webhook').item.json.body;

const severityScore = severityScale[scoring.severity];
const tierWeight = tierWeights[webhook.customer_tier];

if (severityScore === undefined) {
  throw new Error(`Unknown severity value: ${scoring.severity}`);
}
if (tierWeight === undefined) {
  throw new Error(`Unknown customer_tier value: ${webhook.customer_tier}`);
}

// Season multiplier: 1.0 in heating season, 0.7 outside
const inSeason = isHeatingSeason(webhook.received_at);
const seasonMultiplier = inSeason ? 1.0 : 0.7;

// Final priority = severity × tier × season
const finalPriority = severityScore * tierWeight * seasonMultiplier;

return {
  json: {
    ticket_id: scoring.ticket_id,
    received_at: webhook.received_at,
    customer_id: webhook.customer_id,
    customer_type: webhook.customer_type,
    customer_tier: webhook.customer_tier,
    sender_email: webhook.sender_email,
    subject: webhook.subject,
    severity: scoring.severity,
    severity_score: severityScore,
    tier_weight: tierWeight,
    in_heating_season: inSeason,
    season_multiplier: seasonMultiplier,
    final_priority: finalPriority,
    confidence: scoring.confidence,
    severity_reasoning: scoring.severity_reasoning,
    processed_at: new Date().toISOString()
  }
};

textOptions.schema:
{
  "title": "ScoringOutput",
  "description": "Severity assessment for a triaged ticket. Output of the scoring LLM.",
  "type": "object",
  "additionalProperties": false,
  "required": ["ticket_id", "severity", "severity_reasoning", "confidence"],
  "properties": {
    "ticket_id": {
      "type": "string",
      "description": "Pass-through identifier from the extraction step."
    },
    "severity": {
      "type": "string",
      "enum": ["low", "medium", "high", "critical"],
      "description": "Ordered severity level. critical > high > medium > low. When uncertain between adjacent levels, pick the higher."
    },
    "severity_reasoning": {
      "type": "string",
      "maxLength": 200,
      "description": "One short sentence in German explaining the primary reason for the severity assignment."
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "Relative confidence signal for ranking. NOT a calibrated probability."
    }
  }
}
